class Solution:
    def canConstructUniformParity(self, nums1):
        n = len(nums1)
        def rec(i, par):
            if i == n: return True
            if nums1[i] % 2 == par and rec(i + 1, par): return True
            for j in range(n):
                if j != i and nums1[i] - nums1[j] >= 1 and (nums1[i] - nums1[j]) % 2 == par:
                    if rec(i + 1, par): return True
            return False
        return rec(0, 0) or rec(0, 1)

