            for (int j = 0; j < n; j++)
                if (j != i && nums1[i] - nums1[j] >= 1 && (nums1[i] - nums1[j]) % 2 == par)
                    if (rec(i + 1, par)) return true;
            return false;
        };
        return rec(0, 0) || rec(0, 1);
    }
};

