        a = nums1; n = a.length;
        return rec(0, 0) || rec(0, 1);
    }
    private boolean rec(int i, int par) {
        if (i == n) return true;
        if (((a[i] % 2) + 2) % 2 == par && rec(i + 1, par)) return true;
        for (int j = 0; j < n; j++)
            if (j != i && a[i] - a[j] >= 1 && (a[i] - a[j]) % 2 == par)
                if (rec(i + 1, par)) return true;
        return false;
    }
}

