class Solution {
public:
    bool canConstructUniformParity(vector<int>& nums1) {
        int minOdd = INT_MAX, minEven = INT_MAX;
        for (int x : nums1) {
            if (x % 2) minOdd = min(minOdd, x);
            else minEven = min(minEven, x);
        }
        if (minOdd == INT_MAX || minEven == INT_MAX) return true;
        return minOdd < minEven;
    }
};

