class Solution {
    public boolean canConstructUniformParity(int[] nums1) {
        int minOdd = Integer.MAX_VALUE, minEven = Integer.MAX_VALUE;
        for (int x : nums1) {
            if (x % 2 != 0) minOdd = Math.min(minOdd, x);
            else minEven = Math.min(minEven, x);
        }
        if (minOdd == Integer.MAX_VALUE || minEven == Integer.MAX_VALUE) return true;
        return minOdd < minEven;
    }
}

